        sh:select """
            PREFIX : <http://example.org/schema#>

            SELECT ?this
            WHERE {
                ?this a :Applicant .
                FILTER NOT EXISTS {
                    ?this :hasRegularBenefitRecord ?record .
                    ?record :regularBenefitStartDate ?startDate ;
                            :regularBenefitMonthsPaid ?monthsPaid .
                    FILTER (?monthsPaid >= 12)
                }
            }
        """ ;
    ] .

ex:continuous_unemployment_registration_condition_shape
    a sh:NodeShape ;
    sh:targetClass :Applicant ;
    sh:sparql [
        a sh:SPARQLConstraint ;
        sh:message "Applicant has not remained continuously registered as unemployed for at least 12 months." ;
        sh:select """
            PREFIX : <http://example.org/schema#>

            SELECT ?this
            WHERE {
                ?this a :Applicant .
                FILTER NOT EXISTS {
                    ?this :hasUnemploymentRegistration ?registration .
                    ?registration :registrationStartDate ?startDate ;
                                  :isCurrentlyRegistered true .

                    BIND(
                        ((YEAR(now()) * 12 + MONTH(now())) -
                         (YEAR(?startDate) * 12 + MONTH(?startDate)))
                        AS ?elapsedMonths
                    )

                    FILTER (?elapsedMonths >= 12)
                }
            }
        """ ;
    ] .

