    a sh:NodeShape ;
    sh:targetClass :Applicant ;
    sh:sparql [
        a sh:SPARQLConstraint ;
        sh:message "Application was not submitted within two months after the end of the 12-month regular unemployment benefit." ;
        sh:select """
            PREFIX : <http://example.org/schema#>

            SELECT ?this
            WHERE {
                ?this a :Applicant .
                FILTER NOT EXISTS {
                    ?this :hasRegularBenefitRecord ?record .
                    ?record :regularBenefitStartDate ?startDate ;
                            :regularBenefitMonthsPaid ?monthsPaid .

                    BIND(
                        ((YEAR(now()) * 12 + MONTH(now())) -
                         (YEAR(?startDate) * 12 + MONTH(?startDate)))
                        AS ?elapsedMonths
                    )

                    FILTER (
                        ?monthsPaid >= 12 &&
                        ?elapsedMonths >= 12 &&
                        ?elapsedMonths <= 14
                    )
                }
            }
        """ ;
    ] .

ex:annual_family_income_threshold_condition_shape
    a sh:NodeShape ;
    sh:targetClass :Applicant ;
    sh:sparql [
        a sh:SPARQLConstraint ;
        sh:message "Annual family income exceeds the permitted threshold of EUR 10,000 plus EUR 586.08 for each dependent child under 18." ;
        sh:select """
            PREFIX : <http://example.org/schema#>

            SELECT ?this
            WHERE {
                {
                    SELECT ?this (COUNT(DISTINCT ?child) AS ?dependentChildCount)
                    WHERE {
                        ?this a :Applicant .
                        OPTIONAL {
                            ?this :hasChild ?child .
                            ?child :birthDate ?childBirthDate .

                            BIND((YEAR(now()) - YEAR(?childBirthDate)) AS ?childAge)

                            FILTER (?childAge < 18)
                        }
                    }
                    GROUP BY ?this
                }

                {
                    SELECT ?this (SUM(?incomeAmount) AS ?totalFamilyIncome)
                    WHERE {
                        SELECT DISTINCT ?this ?incomeRecord ?incomeAmount
                        WHERE {
                            {
                                ?this :hasIncome ?incomeRecord .
                                ?incomeRecord :amount ?incomeAmount ;
                                              :incomeYear ?incomeYear .
                                FILTER (STR(?incomeYear) = STR(YEAR(now()) - 2))
                            }
                            UNION
                            {
                                ?this :hasSpouse ?spouse .
                                ?spouse :hasIncome ?incomeRecord .
                                ?incomeRecord :amount ?incomeAmount ;
                                              :incomeYear ?incomeYear .
                                FILTER (STR(?incomeYear) = STR(YEAR(now()) - 2))
                            }
                            UNION
                            {
                                ?this :hasChild ?child .
                                ?child :birthDate ?childBirthDate ;
                                       :hasIncome ?incomeRecord .
                                ?incomeRecord :amount ?incomeAmount ;
                                              :incomeYear ?incomeYear .

                                BIND((YEAR(now()) - YEAR(?childBirthDate)) AS ?childAge)

                                FILTER (
                                    ?childAge < 18 &&
                                    STR(?incomeYear) = STR(YEAR(now()) - 2)
                                )
                            }
                        }
                    }
                    GROUP BY ?this
                }

